-- State transitions declared for ConversionJob: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.conversion_jobs_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('completed', 'pending'), ('failed', 'pending'), ('pending', 'cancelled'), ('pending', 'processing'), ('processing', 'cancelled'), ('processing', 'completed'), ('processing', 'failed'), ('processing', 'processing'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: conversion_jobs.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_conversion_jobs__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS conversion_jobs_status_transition_check ON bucket.conversion_jobs;
CREATE TRIGGER conversion_jobs_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.conversion_jobs
    FOR EACH ROW EXECUTE FUNCTION bucket.conversion_jobs_status_transition_check();
